-- V190: ещё 3 объёмные лекции Чертогов (week 127-129)
-- Темы: стропы и такелаж, зимняя вахта, питание на вахте 30/60
BEGIN;

-- ════════════════════════════════════════════════════════════════════════════
-- WEEK 127: Стропы и такелаж — типы, грузоподъёмность, центр тяжести
-- ════════════════════════════════════════════════════════════════════════════

WITH lesson AS (
  INSERT INTO academy_lessons
    (week_number, saga, title, cover_icon, cover_color, estimated_minutes, tags,
     status, generated_by, blocks, is_mandatory, published_at, release_monday)
  VALUES (
    127, 'Подъём и такелаж', 'Стропы: грузоподъёмность, угол, центр тяжести',
    '🪝', '#2a1d3a', 7,
    ARRAY['строповка','такелаж','подъём','аттестация'],
    'published', 'manual',
    $blocks$[
      {"type":"cover","icon":"🪝","title":"Стропы: грузоподъёмность, угол, центр тяжести","subtitle":"Как поднять 20 тонн и не убить человека"},
      {"type":"intro","text":"Каждый второй несчастный случай на стройке связан с подъёмными операциями. Сорвался груз — кран рушится, людей придавливает. Большинство этих случаев — не отказ техники, а строповка. Стропальщик-новичок цепляет на «авось», не считая нагрузку на ветвь, не глядя на центр тяжести, не проверяя коуш и крюк. Опытный — за 30 секунд оценит вес, угол строп, точки крепления и сразу видит, какие стропы нужны. Эта лекция — про эти 30 секунд."},
      {"type":"text_block","title":"Виды строп и их грузоподъёмность","text":"На промысле применяют 4 основных вида строп: канатные (стальные, СКП), цепные (СЦ), текстильные ленточные (СТП) и круглопрядные (СКК, в обиходе «трубы»). У каждого свои плюсы и минусы. Стальной канатный — самый прочный и термостойкий, держит до +400°C, но тяжёлый и царапает груз. Цепной — для очень тяжёлых грузов и температур до 200°C, плюс легко регулируется длина. Ленточный — лёгкий, не повреждает покрытие, гибкий, но боится острых кромок и температур выше 100°C. Круглопрядный — компактный, мягкий, для деликатных грузов, грузоподъёмность как у ленточного. Грузоподъёмность стропа маркируется на бирке и не должна превышаться никогда."},
      {"type":"icon_grid","title":"Цвета ленточных строп — определи грузоподъёмность с 10 метров","items":[
        {"icon":"💜","label":"Фиолетовый — 1 тонна","desc":"Одинарный, ширина 30 мм. Лёгкий монтаж, мелкие детали"},
        {"icon":"💚","label":"Зелёный — 2 тонны","desc":"Ширина 60 мм. Стандарт для электродвигателей, насосов малых"},
        {"icon":"💛","label":"Жёлтый — 3 тонны","desc":"Ширина 90 мм. Реакторы малые, трубы Ду300"},
        {"icon":"🩶","label":"Серый — 4 тонны","desc":"Ширина 120 мм. Среднее оборудование"},
        {"icon":"❤️","label":"Красный — 5 тонн","desc":"Ширина 150 мм. Тяжёлая обвязка, большие узлы"},
        {"icon":"🤎","label":"Коричневый — 6 тонн","desc":"Ширина 180 мм. Магистральные трубы, насосы крупные"},
        {"icon":"🩵","label":"Синий — 8 тонн","desc":"Ширина 240 мм. Реакторы, теплообменники"},
        {"icon":"🧡","label":"Оранжевый — 10 тонн и выше","desc":"Ширина 300+ мм. Сверхтяжёлое — буровые лебёдки, мачты"}
      ]},
      {"type":"text_block","title":"Угол между ветвями — почему меняется нагрузка","text":"Когда груз цепляют двумя или четырьмя стропами, нагрузка на каждую ветвь зависит от угла между ними. Если ветви вертикальные (угол 0°) — каждая держит половину груза. Если угол расходится до 60° — нагрузка на ветвь уже не половина, а 58% от веса груза. При 90° — 71%, при 120° — 100% (то есть каждая ветвь держит ВЕСЬ груз, как будто другой и нет!). При 150° — катастрофические 386%, ветвь рвётся при любом грузе. Поэтому угол между ветвями стропа ВСЕГДА должен быть не больше 90°. Это правило, написанное кровью."},
      {"type":"warning","level":"danger","text":"Если стропа двухветвевая 2×2 т (4 т максимум при 0°), при угле 90° она выдержит только 2.8 т, а при 120° — всего 2 т. Сценарий: груз 3.5 т, стропа 4 т, угол 120° (распёрло низко) — стропа порвётся, груз упадёт. Всегда оценивай угол ДО подъёма, не во время."},
      {"type":"steps","title":"Алгоритм строповки груза","items":[
        "Узнать ВЕС груза по паспорту, маркировке или табличке. На глаз вес определять — запрещено",
        "Найти центр тяжести: на маркированных грузах есть знак ⊕ или ©. На немаркированных — где ширина и высота уравновешены",
        "Выбрать стропы по весу с запасом 1.5: для груза 3 т — стропа минимум 4.5 т грузоподъёмности",
        "Проверить угол строповки: ветви не должны расходиться больше 90° от вертикали",
        "Поставить защиту под острые кромки — текстильные стропы режутся об угол даже за 1 подъём",
        "Натянуть стропы по 50 см без груза, проверить что узлов и захлёстов нет",
        "Подать сигнал крановщику «вирай помалу» (поднять чуть-чуть). Проверить — не кренится ли груз",
        "Опустить, поправить если кренится. Только после ровного подвеса — основной подъём"
      ]},
      {"type":"text_block","title":"Центр тяжести — почему груз кренится","text":"Если стропы зацепить НЕ над центром тяжести, груз перекосится и может упасть. Симметричные грузы (трубы одинакового диаметра, ящики прямоугольные) — центр в геометрическом центре, всё просто. Несимметричные грузы (электродвигатель с редуктором, реактор с штуцером, трансформатор с радиаторами) — центр смещён в сторону тяжёлой части. На таких грузах ВСЕГДА есть маркировка центра тяжести (значок ⊕ или ©). Если её нет — груз поднимать без согласования с мастером запрещено: нужно ставить пробным методом, поднимать на 10-20 см и смотреть угол подвеса."},
      {"type":"icon_grid","title":"Сигналы крановщику — выучить, как алфавит","items":[
        {"icon":"☝️","label":"Указательный палец вверх","desc":"Поднять груз вверх, плавно"},
        {"icon":"👇","label":"Палец вниз","desc":"Опустить вниз, плавно"},
        {"icon":"✋","label":"Открытая ладонь, кулак потом","desc":"СТОП! Немедленно прекратить движение"},
        {"icon":"🤚","label":"Кисть подаёт «помедленнее»","desc":"Снизить скорость движения"},
        {"icon":"🫳","label":"Жест «оба больших пальца вниз и наружу»","desc":"Опустить стрелу"},
        {"icon":"📞","label":"Радиосвязь обязательна для удалённых работ","desc":"Без визуального контакта — только рация, чёткие команды"}
      ]},
      {"type":"fact_card","icon":"💔","text":"2017 год, ХМАО. Стропальщик-новичок зацепил электродвигатель с редуктором (вес 3.2 т) симметрично, не глянув на маркировку центра тяжести. Двигатель имел смещение центра в сторону редуктора. При подъёме груз накренился под углом 35° к крану. Стропа на лёгкой стороне ослабла и сошла с крюка. Двигатель сорвался с высоты 8 м, попал на стропальщика. Смертельный исход. Расследование: центр тяжести был промаркирован на корпусе двигателя символом ⊕ со смещением 40 см. Стропальщик не имел аттестации, цеплял по принципу «по углам, чтоб не падало»."},
      {"type":"text_block","title":"Браковка стропа — когда списать","text":"Стропа имеет ограниченный ресурс и осматривается перед каждым применением. Стальные канатные стропы: списать при обрыве 5 проволок на участке длиной 6 диаметров каната или при износе/коррозии больше 7% сечения. Цепные: при удлинении звена больше 5% от первоначального размера, при погнутом или сточенном звене больше чем на 10% сечения. Текстильные ленточные: при разрезах глубже 10% от ширины, при пятнах краски/масла больше 5 см², при истирании волокон до видимых нитей основы, при повреждении бирки (нет данных грузоподъёмности — стропу запрещено применять)."},
      {"type":"warning","level":"danger","text":"Текстильная стропа без бирки — это «слепая» стропа. Грузоподъёмность неизвестна, дата изготовления неизвестна, срок годности неизвестен. Применять её НЕЛЬЗЯ ни при каких условиях. Если бирка отвалилась — стропа в мусор. Чувство «она ещё крепкая» — лжёт."},
      {"type":"steps","title":"Проверка стропа перед подъёмом — 60 секунд","items":[
        "Бирка на месте, читается, не выцветшая? Видно грузоподъёмность и дату?",
        "Срок годности не истёк? Канатные — 1 год, цепные — 1 год, текстильные — 2-4 года в зависимости от условий",
        "Канатные: пройти рукой по всей длине (в перчатке!) — нет ли обломанных проволок, заусенцев, коррозии",
        "Цепные: каждое звено визуально проверить — нет ли удлинения, трещин, износа",
        "Текстильные: визуальный осмотр на разрезы, обугливание, химические пятна, повреждение оболочки",
        "Коуш и крюк: нет ли деформации, разворота, трещин в местах сопряжения с канатом"
      ]},
      {"type":"text_block","title":"Опасные зоны при подъёме — где НЕ стоять","text":"Под поднятым грузом — самое опасное место в строительной отрасли. Сорвался ли строп, оборвался ли канат лебёдки, лопнул ли элемент крана — груз падает за секунды и не оставляет шансов. Опасная зона — это окружность радиусом высоты подъёма груза плюс длина пути возможного скольжения. Поднимаешь на 10 м — отойди минимум на 10 м от траектории. При работе кранов опасную зону огораживают сигнальной лентой, ставят знаки и наблюдателя. Стропальщик в опасной зоне — только во время крепления и расстройки строп, остальное время вне зоны."},
      {"type":"fact_card","icon":"⭐","text":"Бригадир такелажников Анатолий Петренко, Сургут, 28 лет опыта, ни одного несчастного случая в его смене. Его правило: «Прежде чем поднимать, я три раза прохожу вокруг груза. Первый — смотрю вес. Второй — смотрю центр. Третий — смотрю, кто будет рядом. Только после этого зацепляю». На своём участке его называют «дед-три-круга». В 2025 году его бригада подняла 2400 единиц оборудования общим весом 47 000 тонн. Без единой аварии."}
    ]$blocks$::jsonb,
    true, NOW(),
    (DATE_TRUNC('week', CURRENT_DATE) + INTERVAL '14 days')::date
  )
  RETURNING id
)
INSERT INTO academy_quiz_questions (lesson_id, sort_order, question_type, question_text, options, correct_explanation)
SELECT lesson.id, q.so, q.qt, q.qtext, q.opts::jsonb, q.expl FROM lesson, (VALUES
  (1, 'choice', 'Какая грузоподъёмность у зелёного ленточного стропа стандарта DIN?',
   '[{"id":1,"text":"1 тонна","is_correct":false},{"id":2,"text":"2 тонны","is_correct":true},{"id":3,"text":"3 тонны","is_correct":false},{"id":4,"text":"5 тонн","is_correct":false}]',
   'Зелёный ленточный строп — 2 тонны (ширина 60 мм). Фиолетовый — 1 т, жёлтый — 3 т, красный — 5 т. Цвета стандартизированы DIN 60005 и применяются по всему миру.'),
  (2, 'choice', 'Максимально допустимый угол между ветвями двухветвевого стропа:',
   '[{"id":1,"text":"45°","is_correct":false},{"id":2,"text":"90°","is_correct":true},{"id":3,"text":"120°","is_correct":false},{"id":4,"text":"180°","is_correct":false}]',
   'При угле больше 90° нагрузка на каждую ветвь резко возрастает: при 120° ветвь держит уже 100% веса (как будто другой нет), при 150° — 386%. Это разрыв любой стропы. Правило: угол не больше 90°.'),
  (3, 'truefalse', 'Текстильную стропу без бирки можно применять, если визуально она целая.',
   '[{"id":1,"text":"Верно","is_correct":false},{"id":2,"text":"Неверно","is_correct":true}]',
   'Без бирки неизвестна грузоподъёмность, дата изготовления, срок годности. Это «слепая» стропа — применять запрещено. Если бирка отвалилась — стропа списывается, как бы крепко она ни выглядела.'),
  (4, 'choice', 'Запас грузоподъёмности при выборе стропа должен быть:',
   '[{"id":1,"text":"Не менее 10%","is_correct":false},{"id":2,"text":"Не менее 1.5 крат (50%)","is_correct":true},{"id":3,"text":"3 крата","is_correct":false},{"id":4,"text":"Запас не нужен — берём ровно по весу","is_correct":false}]',
   'Запас минимум 1.5: для груза 3 т — стропа грузоподъёмностью не менее 4.5 т. Это покрывает динамические нагрузки при разгоне/торможении, неровность подъёма, угол строп, износ стропа.'),
  (5, 'scenario', 'Тебе дали стропу 2 т для подъёма груза 1.8 т. Угол между ветвями — 100°. Что делаешь?',
   '[{"id":1,"text":"Поднимаю — запас грузоподъёмности есть","is_correct":false},{"id":2,"text":"Отказываюсь работать, прошу стропу большей грузоподъёмности или сменить угол","is_correct":true},{"id":3,"text":"Поднимаю плавно, без рывков","is_correct":false},{"id":4,"text":"Сокращаю длину строп до 30 см","is_correct":false}]',
   'Угол 100° означает нагрузку 78% веса на ветвь, плюс запас 1.5 = расчётная нагрузка 2.1 т, а стропа 2 т. Это перегрузка. Решение — взять стропу 3 т ИЛИ сделать длиннее, чтобы угол был меньше 90°. Поднимать «плавно» риск не уменьшает.'),
  (6, 'choice', 'Где найти точку центра тяжести на промышленном оборудовании?',
   '[{"id":1,"text":"Всегда в геометрическом центре","is_correct":false},{"id":2,"text":"На маркировке символом ⊕ или ©","is_correct":true},{"id":3,"text":"Определяют на глаз","is_correct":false},{"id":4,"text":"В паспорте оборудования","is_correct":false}]',
   'На промышленном оборудовании центр тяжести маркируется символом ⊕ или © на корпусе. Для несимметричных грузов (мотор с редуктором, реактор со штуцером) центр смещён. Если маркировки нет — поднимать через пробный подвес 10-20 см и регулировать.'),
  (7, 'truefalse', 'Канатная стропа списывается, если на участке 6 диаметров обнаружено 5 обрывов проволок.',
   '[{"id":1,"text":"Верно","is_correct":true},{"id":2,"text":"Неверно","is_correct":false}]',
   'По нормативу 5 обрывов проволок на участке длиной 6 диаметров каната — браковочный признак. Также списывается при коррозии больше 7% сечения, при заломе и узлах. Регулярная проверка — перед КАЖДЫМ подъёмом.'),
  (8, 'scenario', 'Крановщик стоит за кабиной, не видит груз. Связи нет. Стропальщик хочет подать сигнал. Что делать?',
   '[{"id":1,"text":"Махать руками громко — крановщик увидит в зеркало","is_correct":false},{"id":2,"text":"Запретить работу до организации радиосвязи или прямого визуального контакта","is_correct":true},{"id":3,"text":"Назначить второго стропальщика для передачи сигналов","is_correct":false},{"id":4,"text":"Поднимать без сигнала медленно","is_correct":false}]',
   'Без визуального контакта или радиосвязи подъёмные работы ЗАПРЕЩЕНЫ. Это правило безопасности №1. Сигнальщик-посредник может ошибиться (испорченный телефон). Радиосвязь — обязательное условие. Кран простоит — это деньги, но не жизнь.'),
  (9, 'choice', 'Опасная зона при подъёме груза на высоту 10 м:',
   '[{"id":1,"text":"Не менее 3 м","is_correct":false},{"id":2,"text":"Не менее 5 м","is_correct":false},{"id":3,"text":"Не менее 10 м","is_correct":true},{"id":4,"text":"Где удобно","is_correct":false}]',
   'Опасная зона = высота подъёма плюс возможный путь скольжения груза. Поднимаешь на 10 м — опасная зона минимум 10 м. На высоту больше 15 м опасная зона ещё шире — груз может улететь по дуге. Стропальщик во время подъёма — вне опасной зоны.'),
  (10, 'choice', 'Что делать, если груз накренился при подъёме на 20 см?',
   '[{"id":1,"text":"Поднимать дальше, на высоте выровняется","is_correct":false},{"id":2,"text":"Опустить, перецепить стропы по центру тяжести","is_correct":true},{"id":3,"text":"Подержать за нижний край и продолжать подъём","is_correct":false},{"id":4,"text":"Натянуть оттяжку и продолжать","is_correct":false}]',
   'Если груз накренился — стропа была зацеплена не по центру тяжести. Опустить, осмотреть, перецепить. Поднимать накренённый груз нельзя: при подъёме крен усиливается, может выскользнуть из строп, мерцающие нагрузки рвут крепёж. «Подержать» снизу = быть под грузом, это смертельная ошибка.'),
  (11, 'scenario', 'Бригада торопится: «Нет нужной стропы, ставь две одинаковые». Груз 4 т, две стропы по 2 т. Что делаешь?',
   '[{"id":1,"text":"Ставлю две — суммарная грузоподъёмность 4 т, как раз","is_correct":false},{"id":2,"text":"Отказываюсь — запаса 1.5 нет, при любом угле выше 0° перегруз","is_correct":true},{"id":3,"text":"Ставлю три стропы по 2 т","is_correct":false},{"id":4,"text":"Ставлю две и поднимаю плавно","is_correct":false}]',
   'Без запаса 1.5 — 2+2=4 т на груз 4 т недостаточно. При угле 60° каждая ветвь будет нести 2.3 т (перегруз стропы 2 т). Решение — либо одна стропа 6 т, либо две стропы 4 т каждая. Бригаде объяснить риск, мастеру сообщить. «Плавно» при перегрузе не работает — стропа порвётся всё равно.'),
  (12, 'truefalse', 'Стальной канатный строп можно применять при температуре груза +400°C.',
   '[{"id":1,"text":"Верно","is_correct":true},{"id":2,"text":"Неверно","is_correct":false}]',
   'Стальные канатные стропы рассчитаны на температуру до +400°C. Цепные — до +200°C. Текстильные ленточные — до +100°C, выше испаряется пропитка волокон. Для горячих грузов (печи, реакторы после остановки) — только стальные.')
) AS q(so, qt, qtext, opts, expl);


-- ════════════════════════════════════════════════════════════════════════════
-- WEEK 128: Зимняя вахта — обморожения, гипотермия, миф про спирт
-- ════════════════════════════════════════════════════════════════════════════

WITH lesson AS (
  INSERT INTO academy_lessons
    (week_number, saga, title, cover_icon, cover_color, estimated_minutes, tags,
     status, generated_by, blocks, is_mandatory, published_at, release_monday)
  VALUES (
    128, 'Север и вахта', 'Зимняя вахта: обморожение, гипотермия, мифы',
    '❄️', '#0e1e36', 7,
    ARRAY['зима','обморожение','гипотермия','здоровье'],
    'published', 'manual',
    $blocks$[
      {"type":"cover","icon":"❄️","title":"Зимняя вахта: обморожение, гипотермия, мифы","subtitle":"Минус 40 на улице — и человек погибает за 45 минут"},
      {"type":"intro","text":"На севере мороз убивает тихо. Не как огонь — медленно, без боли. Сначала немеет нос и уши, потом руки. Потом приходит сонливость, и человек хочет лечь. Если лёг — больше не встал. По статистике, 60% смертей от переохлаждения — это люди, которые поняли, что им холодно, но «потерпели ещё пять минут». Этой лекции учат не тому, как одеться — это очевидно. А тому, как выжить, когда что-то пошло не так: вездеход застрял в тундре, генератор замёрз, рукавицы потеряны."},
      {"type":"text_block","title":"Слои одежды — почему три, а не один","text":"Зимняя одежда работает по принципу «трёх слоёв»: первый (термобельё) отводит пот от тела, второй (флис, шерсть) удерживает тепло, третий (мембранная куртка) защищает от ветра и снега. Если надеть только толстую шубу без термобелья — пот скапливается на коже, замерзает, и человек замерзает ИЗНУТРИ при -10°C. Хлопковое бельё в мороз — самый опасный выбор: впитывает пот, не высыхает, охлаждает тело сильнее голой кожи. Только синтетика (полартек, термолайт) или мериносовая шерсть."},
      {"type":"icon_grid","title":"Слои зимней одежды на промысле","items":[
        {"icon":"1️⃣","label":"Первый: термобельё","desc":"Синтетика или меринос. Отводит пот. Хлопок ЗАПРЕЩЁН"},
        {"icon":"2️⃣","label":"Второй: флис или шерсть","desc":"Удерживает тепло. Толщина по температуре: -10° / -20° / -30° свитеры"},
        {"icon":"3️⃣","label":"Третий: ветрозащита","desc":"Мембранная куртка с капюшоном. Дышит, не пропускает ветер и снег"},
        {"icon":"🧤","label":"Перчатки + рукавицы","desc":"Тонкие перчатки внутри, рукавицы поверх. Перчатки одни — рука стынет за 5 минут"},
        {"icon":"🥾","label":"Унты или сапоги -50°","desc":"Только специальные. Кирзачи в -30°C = обморожение пальцев"},
        {"icon":"😷","label":"Балаклава","desc":"Закрывает нос, щёки, шею. Открытая кожа на -30°C обмораживается за 3 минуты"}
      ]},
      {"type":"text_block","title":"Обморожение — как развивается, что делать","text":"Обморожение бывает 4 степеней. Первая — кожа белая или бледно-синяя, ощущение покалывания. Согревается полностью без последствий. Вторая — пузыри с прозрачной жидкостью, как при ожоге. Заживает с шелушением кожи. Третья — кровянистые пузыри, чёрные участки, гибель кожи. Может потребоваться пересадка. Четвёртая — омертвение всей толщи тканей, включая мышцы и кости. Часто заканчивается ампутацией пальцев, носа, ушей. Время развития: при -20°C голая кожа замерзает за 8-12 минут, при -30°C — за 4-6 минут, при -40°C с ветром — за 1-2 минуты."},
      {"type":"warning","level":"danger","text":"Растирать обморожение снегом — НЕЛЬЗЯ. Кристаллы льда дополнительно повреждают замёрзшие ткани. Тереть рукой шерстяной варежкой — тоже нельзя, такое же повреждение. Правильно: завести пострадавшего в тёплое помещение, СОГРЕТЬ ВОДОЙ +20-25°C постепенно повышая до +37°C, дать тёплое сладкое питьё. Алкоголь СТРОГО запрещён."},
      {"type":"text_block","title":"Гипотермия — общее переохлаждение организма","text":"Гипотермия — это снижение температуры тела ниже 35°C. При 35°C начинается дрожь — это попытка организма согреться. При 32°C дрожь прекращается (это плохой знак — мышцы устали), начинается сонливость, спутанность сознания. При 30°C человек засыпает и теряет сознание. При 28°C наступает остановка сердца. От первых признаков до смерти — 30-60 минут на морозе без укрытия. Сильно ускоряют гипотермию: мокрая одежда (испарение охлаждает в 25 раз быстрее), ветер (минус 10°C к температуре на каждые 10 м/с), алкоголь (расширяет сосуды, тепло уходит из организма)."},
      {"type":"icon_grid","title":"Стадии гипотермии — как определить","items":[
        {"icon":"🥶","label":"35-33°C: дрожь сильная","desc":"Сознание ясное. Срочно в тепло, тёплое питьё. Можно восстановиться сам"},
        {"icon":"😵","label":"33-30°C: дрожь прекращается","desc":"Спутанность, неловкость, апатия. Опасное состояние — медпомощь"},
        {"icon":"💀","label":"30-28°C: потеря сознания","desc":"Зрачки расширены, пульс слабый. Реанимация, скорая, госпитализация"},
        {"icon":"⚰️","label":"Ниже 28°C: остановка сердца","desc":"СЛР, согревание, скорая. Прогноз тяжёлый"}
      ]},
      {"type":"warning","level":"danger","text":"Самая опасная фаза — когда человеку «уже не холодно». Это значит организм сдался, температура упала ниже 33°C. Появляется иллюзия тепла, человек начинает раздеваться (парадоксальное раздевание — известный симптом). Найти раздетое тело в сугробе — это часто гипотермия. Если коллега снимает шапку «жарко» при -30°C — срочно в тепло, это критическое состояние."},
      {"type":"steps","title":"Что делать при гипотермии","items":[
        "Перенести в тёплое помещение или укрытие. На улице — обернуть всем, что есть: куртки, спальник, плёнка",
        "Снять мокрую одежду — она охлаждает в 25 раз быстрее воздуха. Обнажить, насухо вытереть, одеть сухое",
        "Согревать ИЗНУТРИ: тёплый сладкий чай, бульон. НЕ горячий — обожжёт пищевод",
        "Согревать тело центрально: грелка/бутылка с тёплой водой на грудь, живот, под мышки, в пах. НЕ на конечности",
        "Контакт «кожа к коже» — раздеть пострадавшего и обернуть собой под одеялом. Передача тепла телом эффективна",
        "Постоянно говорить с пострадавшим, не давать заснуть. Сон при гипотермии — смерть",
        "Вызвать медпомощь. При тяжёлой гипотермии (без сознания) — СЛР, эвакуация"
      ]},
      {"type":"text_block","title":"Спирт в мороз — самый опасный миф","text":"Многие думают: «выпил, согрелся». Это иллюзия. Алкоголь расширяет сосуды кожи, кровь приливает — кажется тепло. На самом деле кровь охлаждается на поверхности и возвращается к сердцу холодной. Внутренняя температура тела падает БЫСТРЕЕ, чем без алкоголя. Плюс алкоголь притупляет ощущение холода и сонливость — человек не понимает, что замерзает. По статистике, 70% жертв переохлаждения на севере были выпившими. Бутылка водки в кармане на вахте — это не страховка, это билет в один конец."},
      {"type":"fact_card","icon":"🌨️","text":"Январь 2018, Уренгой. Вездеход сломался в 40 км от базы, температура -42°C с ветром 8 м/с. Бригада из 4 человек: трое в тёплых полушубках, один в кирзачах и стёганке. Старший вызвал помощь по рации, велел жечь сиденья и ждать в кабине, не выходить. Через 3.5 часа подъехала вторая машина. Все четверо живы, обморожений нет. Старший сказал спасателям: «Главное — никто не выпил. Был у нас один с фляжкой, я её отнял силой». Если бы выпили — могло быть иначе. Замёрзшие сиденья в +5°C спасли четыре жизни."},
      {"type":"steps","title":"Аварийная ситуация в тундре — алгоритм","items":[
        "Не выходить из машины пока не оценена обстановка. Машина — укрытие от ветра, который убивает быстрее холода",
        "Связь: попытаться вызвать помощь по рации, спутниковому телефону, через коллег",
        "Заглушить двигатель НЕЛЬЗЯ если есть бензин — нужно тепло. Окно приоткрыть на 2 см от угара",
        "Если бензина нет — жечь всё что горит: сиденья, обивка, документы. Открыть окно от угара",
        "Не лежать на снегу — теряешь тепло в 5 раз быстрее. Сидеть, шевелить пальцами, не давать заснуть",
        "Если выходишь искать помощь — оставить записку в машине: куда пошёл, во сколько, маршрут",
        "Идти строго по компасу. Тундра вся одинаковая, без ориентиров можно ходить кругами часами"
      ]},
      {"type":"fact_card","icon":"🦊","text":"Чукотка, 1956 год. Геолог Андрей Зимин потерял группу в пурге, остался один. Найти его смогли через 4 дня. Он построил снежное укрытие (иглу), грелся костром из карликовой берёзы и нерпы (привезёнными как образцы), ел жидкую кашу из крупы и снега. Температура была -47°C. Спасся, обморожений было минимум — кончики пальцев. Из его дневника: «Сел и подумал — что у меня есть. Спички. Спирт оставить — это смерть. Лучшее моё оружие — голова. С неё и начал»."}
    ]$blocks$::jsonb,
    true, NOW(),
    (DATE_TRUNC('week', CURRENT_DATE) + INTERVAL '21 days')::date
  )
  RETURNING id
)
INSERT INTO academy_quiz_questions (lesson_id, sort_order, question_type, question_text, options, correct_explanation)
SELECT lesson.id, q.so, q.qt, q.qtext, q.opts::jsonb, q.expl FROM lesson, (VALUES
  (1, 'choice', 'Какое термобельё нельзя надевать в мороз?',
   '[{"id":1,"text":"Полартек","is_correct":false},{"id":2,"text":"Меринос","is_correct":false},{"id":3,"text":"Хлопок","is_correct":true},{"id":4,"text":"Термолайт","is_correct":false}]',
   'Хлопковое бельё впитывает пот, не отводит влагу, не высыхает. В мороз это смертельно — мокрая ткань охлаждает тело в 25 раз быстрее воздуха. Только синтетика (полартек, термолайт) или мериносовая шерсть.'),
  (2, 'choice', 'За сколько минут обмораживается голая кожа при -30°C?',
   '[{"id":1,"text":"30 минут","is_correct":false},{"id":2,"text":"15 минут","is_correct":false},{"id":3,"text":"4-6 минут","is_correct":true},{"id":4,"text":"1 час","is_correct":false}]',
   'При -30°C обморожение голой кожи наступает за 4-6 минут. При -40°C с ветром — за 1-2 минуты. Поэтому балаклава, рукавицы и капюшон обязательны — открытой остаётся только узкая полоса глаз.'),
  (3, 'truefalse', 'Растирать обмороженный участок снегом — правильный метод первой помощи.',
   '[{"id":1,"text":"Верно","is_correct":false},{"id":2,"text":"Неверно","is_correct":true}]',
   'Снегом растирать запрещено — кристаллы льда дополнительно повреждают ткани. Правильно: завести в тёплое помещение, согревать водой +20°C постепенно повышая до +37°C, тёплое сладкое питьё.'),
  (4, 'choice', 'Самый опасный признак гипотермии:',
   '[{"id":1,"text":"Сильная дрожь","is_correct":false},{"id":2,"text":"Прекращение дрожи + «уже не холодно»","is_correct":true},{"id":3,"text":"Покраснение лица","is_correct":false},{"id":4,"text":"Чихание","is_correct":false}]',
   'Прекращение дрожи означает что температура тела упала ниже 33°C — мышцы устали. Появляется иллюзия тепла, парадоксальное раздевание. Это критическая стадия — без помощи человек погибнет за 30-60 минут.'),
  (5, 'truefalse', 'Алкоголь помогает согреться на морозе.',
   '[{"id":1,"text":"Верно","is_correct":false},{"id":2,"text":"Неверно","is_correct":true}]',
   'Алкоголь расширяет сосуды кожи — тепло уходит из организма быстрее. Внутренняя температура падает быстрее без алкоголя. 70% жертв переохлаждения на севере были выпившими. Притупляет ощущение опасности — человек не понимает, что замерзает.'),
  (6, 'scenario', 'Вездеход застрял в тундре, -38°C, ветер. До базы 35 км. У вас 4 человека и работающий двигатель с полным баком. Что делать?',
   '[{"id":1,"text":"Двое пойдут пешком на базу, двое останутся ждать","is_correct":false},{"id":2,"text":"Оставаться в кабине, греться двигателем, ждать помощь, сообщить по рации","is_correct":true},{"id":3,"text":"Все пойдут к базе вместе — теплее в группе","is_correct":false},{"id":4,"text":"Развести костёр у машины и греться","is_correct":false}]',
   'Машина — укрытие от ветра, который убивает быстрее температуры. Двигатель работает = тепло. Связь = шанс на спасение. Идти 35 км в -38°C — смерть для большинства даже опытных. Костёр снаружи бесполезен — ветер сдует тепло, в кабине теплее и безопаснее.'),
  (7, 'choice', 'При какой внутренней температуре тела наступает остановка сердца?',
   '[{"id":1,"text":"35°C","is_correct":false},{"id":2,"text":"33°C","is_correct":false},{"id":3,"text":"28°C","is_correct":true},{"id":4,"text":"25°C","is_correct":false}]',
   'При 28°C наступает остановка сердца. При 35°C — дрожь. При 33°C — прекращение дрожи и опасность. При 30°C — потеря сознания. Чем раньше согреть пострадавшего, тем выше шанс.'),
  (8, 'choice', 'Куда правильно прикладывать грелку при гипотермии?',
   '[{"id":1,"text":"К рукам и ногам","is_correct":false},{"id":2,"text":"К груди, животу, под мышки, в пах","is_correct":true},{"id":3,"text":"К затылку","is_correct":false},{"id":4,"text":"К стопам","is_correct":false}]',
   'Согревать нужно ЦЕНТРАЛЬНО — корпус. Грелка на конечности заставит холодную кровь вернуться к сердцу слишком быстро — это afterdrop, температура тела упадёт ещё ниже, может остановиться сердце. Грудь, живот, под мышки, в пах — крупные сосуды близко к коже.'),
  (9, 'scenario', 'Коллега в -35°C говорит «жарко» и расстёгивает куртку. Что делаешь?',
   '[{"id":1,"text":"Соглашаюсь — он лучше знает","is_correct":false},{"id":2,"text":"Немедленно тащу в тепло — это парадоксальное раздевание, критическая стадия гипотермии","is_correct":true},{"id":3,"text":"Прошу подождать пока разогреется","is_correct":false},{"id":4,"text":"Дам ему попить горячего чая","is_correct":false}]',
   'Чувство тепла при -35°C — это признак критической гипотермии, температура тела упала ниже 33°C. Это парадоксальное раздевание — известный симптом. От этой стадии до остановки сердца 20-40 минут. Срочно в тепло, центральное согревание, медпомощь.'),
  (10, 'choice', 'Хлопковое нижнее бельё в мороз опасно потому что:',
   '[{"id":1,"text":"Натирает кожу","is_correct":false},{"id":2,"text":"Впитывает пот и не отводит, охлаждая тело","is_correct":true},{"id":3,"text":"Стоит дорого","is_correct":false},{"id":4,"text":"Трудно стирать","is_correct":false}]',
   'Хлопок впитывает пот, держит его в волокнах. Пот замерзает на коже, охлаждая тело сильнее голой кожи. Синтетика и меринос отводят влагу наружу, оставляя кожу сухой.'),
  (11, 'scenario', 'Идёшь по тундре от сломавшейся машины к базе 8 км. Через 5 км понимаешь — пурга, видимости нет, компас сломался. Что делать?',
   '[{"id":1,"text":"Продолжать идти в ту же сторону","is_correct":false},{"id":2,"text":"Возвращаться к машине по своим следам, пока они видны","is_correct":true},{"id":3,"text":"Идти на восток — там точно люди","is_correct":false},{"id":4,"text":"Лечь и переждать пургу в снегу","is_correct":false}]',
   'Без компаса в пурге легко ходить кругами — известный эффект «петля смерти». Лучшее решение — вернуться по своим следам, пока они ещё видны (через 30 минут пурга их закроет). Машина — известное укрытие. Идти на восток наугад — смерть. Лечь в снег без укрытия — гипотермия за час.'),
  (12, 'truefalse', 'Унты ватные при -40°C полностью защищают ноги от обморожения.',
   '[{"id":1,"text":"Верно","is_correct":true},{"id":2,"text":"Неверно","is_correct":false}]',
   'Унты (или специальные сапоги, рассчитанные на -50°C) защищают полностью. Но обычные кирзовые сапоги или резиновые в -30°C — это гарантированное обморожение пальцев за 1-2 часа работы. Обувь — главный риск зимой, потому что ноги стоят на холодной поверхности.')
) AS q(so, qt, qtext, opts, expl);


-- ════════════════════════════════════════════════════════════════════════════
-- WEEK 129: Питание на вахте 30/60 — ЖКТ, как не набрать вес, гастрит
-- ════════════════════════════════════════════════════════════════════════════

WITH lesson AS (
  INSERT INTO academy_lessons
    (week_number, saga, title, cover_icon, cover_color, estimated_minutes, tags,
     status, generated_by, blocks, is_mandatory, published_at, release_monday)
  VALUES (
    129, 'Здоровье на вахте', 'Питание 30/60: гастрит, вес, режим',
    '🍲', '#2a1e10', 6,
    ARRAY['питание','жкт','здоровье','вахта'],
    'published', 'manual',
    $blocks$[
      {"type":"cover","icon":"🍲","title":"Питание 30/60: гастрит, вес, режим","subtitle":"Почему 80% вахтовиков к 40 годам имеют гастрит"},
      {"type":"intro","text":"Жесткая правда: после 5-7 лет вахты по 30/60 у 80% работников появляется гастрит, у 50% — холецистит, у 30% — диабет 2 типа. Это не плохая генетика. Это режим: 12-часовая смена, еда раз в 4-5 часов через приём смены, ночные перекусы, маринады и сало в посылках из дома, газировка с пайком, никаких овощей по 2 месяца. ЖКТ не выдерживает. Лекция — не диета и не запреты. Простые правила, которые позволят дойти до пенсии без таблеток."},
      {"type":"text_block","title":"Почему вахта убивает ЖКТ — биология","text":"Желудок работает по биологическим часам: утром выделяет соляную кислоту для завтрака, днём — для обеда, вечером — снижает секрецию. На вахте этот ритм сбивается. Ночная смена — желудок льёт кислоту по ночам, когда нет еды (кислота травмирует слизистую — гастрит). Перевалка на день — старая привычка ещё месяц. Кофе натощак в 4 утра перед сменой — кислота прямо на пустую слизистую. Это плюс к обычным проблемам: переедание после смены, поздний ужин, отсутствие овощей. Через 5-7 лет такого режима — гастрит, гарантированно у большинства."},
      {"type":"icon_grid","title":"Главные враги ЖКТ на вахте","items":[
        {"icon":"☕","label":"Кофе натощак","desc":"Кислота на пустую слизистую = ожог. Только после еды!"},
        {"icon":"🥫","label":"Тушёнка и консервы","desc":"Много соли, жира, мало клетчатки. Запор и тяжесть"},
        {"icon":"🥓","label":"Сало и копчёности","desc":"Тяжёлый жир, нагрузка на печень и желчный. К 40 — холецистит"},
        {"icon":"🍫","label":"Сладкое и газировка","desc":"Скачки сахара. К 50 — диабет 2 типа у каждого третьего"},
        {"icon":"🌭","label":"Лапша быстрого приготовления","desc":"Пальмовое масло, добавки. Замените на нормальную крупу"},
        {"icon":"🚭","label":"Курево натощак","desc":"Прямой путь к язве. Курить только после еды"}
      ]},
      {"type":"text_block","title":"Как организовать питание — 4 простых правила","text":"Правило 1: не пропускать завтрак. Тёплая каша на воде (овсянка, гречка, рис) занимает 10 минут — но защищает желудок на 4-5 часов работы. Правило 2: брать перекус на смену — горсть орехов, банан, варёное яйцо, твёрдый сыр. Это не «много жрать», это нормальный ритм. Правило 3: после смены — суп или жидкое. Желудок устал, тяжёлая еда ляжет камнем. Правило 4: вечером не есть за 3 часа до сна. На вахте поздний ужин = ожирение, рефлюкс, плохой сон. Эти 4 правила соблюдают опытные мужики 25+ лет вахтового стажа без таблеток."},
      {"type":"warning","level":"warning","text":"Никаких «всё съем за раз» при двух смен подряд. Это убивает желудок. Лучше 5 раз по 300 г, чем 2 раза по 800 г. Растянутый объёмом желудок медленно опустошается, кислота накапливается, изжога становится хронической."},
      {"type":"steps","title":"Меню на смену 12 часов — пример рабочего из Сургута","items":[
        "06:00 завтрак: овсянка на воде с маслом и мёдом, чай зелёный, бутерброд с сыром",
        "10:00 первый перекус: банан + горсть миндаля или варёное яйцо",
        "13:00 обед в столовой: суп, второе с гарниром, салат из капусты или огурца, компот",
        "16:00 второй перекус: яблоко + сухари + кефир (если есть)",
        "19:00 ужин: рыба или мясо запечённое, гречка, тушёные овощи, чай травяной",
        "22:00 если работаешь ночь: лёгкий перекус — творог 100 г или йогурт без добавок"
      ]},
      {"type":"text_block","title":"Как не набрать вес на вахте — реальная математика","text":"Средний вахтовик в 30 лет на работе тратит 3000-3500 ккал в день — это много. Если он съедает 4000 ккал (а в столовой легко: каша + котлета + картошка + хлеб с маслом + компот = 1800 ккал за один приём), излишек 500-1000 ккал в день. За месяц — 1.5-3 кг лишнего веса. За год вахт = 18-36 кг. К 40 годам — пузо, давление, диабет. Решение: считать примерно. Завтрак 800 ккал, обед 1000, ужин 800, перекусы 400-600 — итого 3000-3200. Это не голодуха, это норма для тяжёлой работы. Полнота на вахте — это не «возраст», это излишек 500 ккал в день."},
      {"type":"icon_grid","title":"Калорийность типичных блюд столовой","items":[
        {"icon":"🍲","label":"Борщ с мясом 300 мл","desc":"≈ 400 ккал. Хорошее первое"},
        {"icon":"🍗","label":"Котлета свиная с картошкой","desc":"≈ 800 ккал. Запечённая, без панировки"},
        {"icon":"🥩","label":"Гуляш с гречкой","desc":"≈ 700 ккал. Нормальное второе"},
        {"icon":"🥧","label":"Пирожок с мясом","desc":"≈ 350 ккал — обманчивая лёгкость, легко съесть 3 шт = 1050 ккал"},
        {"icon":"🥖","label":"Кусок хлеба + 10 г масла","desc":"≈ 150 ккал. Один — норма, четыре — повод задуматься"},
        {"icon":"🥤","label":"Газировка 0.5 л","desc":"≈ 230 ккал. Замените на воду или несладкий чай"}
      ]},
      {"type":"text_block","title":"Овощи и клетчатка — почему критично на вахте","text":"Без овощей и клетчатки кишечник встаёт. Запор — частая жалоба вахтовиков. Причина: мало клетчатки, мало воды, сидячая поза в технике, стресс смены. Хроническая запор после 5-7 лет ведёт к геморрою, дивертикулёзу, повышает риск рака толстой кишки. Решение — каждый день минимум 300 г овощей в любом виде (свежие, тушёные, в супе) и 2 литра воды. Капуста, морковь, лук — самые дешёвые и доступные на любой столовой. Если столовая бедная — везти с дома лук, яблоки, морковь в герметичной таре, держат 2 недели."},
      {"type":"warning","level":"warning","text":"Курить натощак, пить кофе натощак, не завтракать — три самых частых причины язвы желудка у вахтовиков. К 40 годам у курильщика-вахтовика язва есть в 60% случаев. Лечение язвы на удалённом промысле — это эвакуация в город, недели простоя, потеря зарплаты, иногда хирургия."},
      {"type":"fact_card","icon":"💪","text":"Игорь Скляров, 58 лет, вахтовик с 1992 года, машинист буровой. За 33 года ни одной язвы, ни одного отстранения по здоровью. Его рецепт: «Утром овсянка обязательно, кофе только после неё. На смене всегда варёное яйцо и яблоко в кармане. Вечером супик и салатик. Сало и шашлык — по праздникам. Спиртного нет 12 лет. Я не сижу на диете — я просто ем как нормальный человек, а не как солдат в окопе»."},
      {"type":"steps","title":"Что положить в сумку при сборе на вахту","items":[
        "Овсянка быстрого приготовления (без сахара) — на случай, если в столовой не успел",
        "Орехи смесь 300-500 г — миндаль, грецкий, кешью. Перекус, не портится",
        "Сухофрукты 300 г — курага, чернослив, изюм. От запоров и для энергии",
        "Зелёный чай в пакетиках — лучше чем кофе для желудка",
        "Витамины комплексные — на 30 дней. На вахте овощей мало, авитаминоз обычный",
        "Аптечка ЖКТ: омепразол (или аналоги от изжоги), смекта от диареи, активированный уголь",
        "НЕ брать: алкоголь (запрещён), копчёности (тяжело), много сладкого (искушение)"
      ]},
      {"type":"fact_card","icon":"📊","text":"Газпром нефть в 2023 году провела медобследование 2400 вахтовиков на разных промыслах. Результаты: гастрит в 78% после 5 лет стажа, ожирение 1-2 степени в 54%, гипертония в 41% к 40 годам, диабет 2 типа в 18%. Причина основная — питание. После внедрения программы «здоровая столовая» с обязательными салат-баром, контролем калорий и обучением через подобные лекции, у новичков (стаж 1-3 года) гастрит снизился до 22%. Простые правила работают."}
    ]$blocks$::jsonb,
    false, NOW(),
    (DATE_TRUNC('week', CURRENT_DATE) + INTERVAL '28 days')::date
  )
  RETURNING id
)
INSERT INTO academy_quiz_questions (lesson_id, sort_order, question_type, question_text, options, correct_explanation)
SELECT lesson.id, q.so, q.qt, q.qtext, q.opts::jsonb, q.expl FROM lesson, (VALUES
  (1, 'choice', 'Главная причина гастрита у вахтовиков:',
   '[{"id":1,"text":"Острая еда в столовой","is_correct":false},{"id":2,"text":"Сбитый ритм питания + кофе натощак","is_correct":true},{"id":3,"text":"Холодная погода","is_correct":false},{"id":4,"text":"Плохая вода","is_correct":false}]',
   'Главная причина — нарушение биоритмов: ночные смены, кофе на пустой желудок, нерегулярные приёмы пищи. Желудок выделяет кислоту по часам, при сбое ритма она травмирует слизистую. По статистике после 5-7 лет вахты у 80% работников гастрит — именно от режима.'),
  (2, 'choice', 'Сколько калорий тратит вахтовик за смену 12 часов?',
   '[{"id":1,"text":"1500-2000 ккал","is_correct":false},{"id":2,"text":"2000-2500 ккал","is_correct":false},{"id":3,"text":"3000-3500 ккал","is_correct":true},{"id":4,"text":"5000-6000 ккал","is_correct":false}]',
   'Активная физическая работа 12 часов тратит 3000-3500 ккал. Это много, но если съедать 4000 — за месяц 1.5-3 кг лишнего веса. К 40 годам у среднестатистического вахтовика лишних 18-36 кг.'),
  (3, 'truefalse', 'Кофе натощак перед сменой — нормальная практика.',
   '[{"id":1,"text":"Верно","is_correct":false},{"id":2,"text":"Неверно","is_correct":true}]',
   'Кофе натощак — прямой путь к гастриту и язве. Кислота кофе плюс соляная кислота желудка на пустую слизистую = ожог стенки. Кофе только после еды, лучше через 30-40 минут после завтрака.'),
  (4, 'choice', 'Какой завтрак защищает желудок на 4-5 часов смены?',
   '[{"id":1,"text":"Бутерброд с салом + кофе","is_correct":false},{"id":2,"text":"Каша на воде + чай + бутерброд с сыром","is_correct":true},{"id":3,"text":"Только чёрный кофе","is_correct":false},{"id":4,"text":"Чай и пирожок","is_correct":false}]',
   'Тёплая каша на воде обволакивает слизистую, защищает от кислоты на 4-5 часов работы. Овсянка, гречка или рис + чай + хлеб с сыром — это базовый завтрак опытных вахтовиков.'),
  (5, 'scenario', 'Тебе предстоит ночная смена. В 22:00 заступаешь. Что есть и когда?',
   '[{"id":1,"text":"Плотный ужин в 21:30 — наесться на всю ночь","is_correct":false},{"id":2,"text":"Лёгкий ужин в 19:00, перекус (творог или йогурт) перед сменой, на смене 2 раза по 200 г","is_correct":true},{"id":3,"text":"Не есть до смены, чтобы не клонило в сон","is_correct":false},{"id":4,"text":"Только кофе с печеньем","is_correct":false}]',
   'Плотный ужин перед сменой — тяжесть, рефлюкс, сонливость. Лёгкий ужин в 19:00 и небольшой перекус перед сменой — оптимально. На самой смене разделить еду на 2 приёма по 200-300 г: в 1-2 ночи и в 5-6 утра. Кофе с печеньем = голодный и нервный к утру.'),
  (6, 'choice', 'Какие овощи самые доступные и полезные на вахте?',
   '[{"id":1,"text":"Только свежие из салат-бара","is_correct":false},{"id":2,"text":"Капуста, морковь, лук — свежие и тушёные","is_correct":true},{"id":3,"text":"Помидоры и огурцы зимой","is_correct":false},{"id":4,"text":"Только зелень","is_correct":false}]',
   'Капуста, морковь, лук — самые дешёвые, доступные в любой столовой, хорошо хранятся. Минимум 300 г овощей в день — норма для здорового кишечника. Дорогие тепличные помидоры в феврале — это бонус, но не основа.'),
  (7, 'truefalse', 'Сало и копчёности — оптимальная еда для тяжёлой физической работы.',
   '[{"id":1,"text":"Верно","is_correct":false},{"id":2,"text":"Неверно","is_correct":true}]',
   'Сало и копчёности — тяжёлый жир, нагрузка на печень и желчный пузырь. К 40 годам у любителей сала вахтовиков — холецистит в 50% случаев. По праздникам можно, ежедневно — нельзя.'),
  (8, 'choice', 'Сколько литров воды в день нужно вахтовику?',
   '[{"id":1,"text":"0.5 литра","is_correct":false},{"id":2,"text":"1 литр","is_correct":false},{"id":3,"text":"2 литра","is_correct":true},{"id":4,"text":"5 литров","is_correct":false}]',
   'Норма — 2 литра воды (не считая чая, супа, компота). При нехватке воды густеет кровь, страдает кишечник (запор), почки. На жаре или при тяжёлой работе может потребоваться 3-4 литра.'),
  (9, 'scenario', 'Ты заметил, что у тебя последние 2 недели изжога каждый вечер после столовой. Что делать?',
   '[{"id":1,"text":"Пить таблетки от изжоги перед каждой едой","is_correct":false},{"id":2,"text":"Уменьшить порцию ужина, не есть за 3 часа до сна, проверить остроту и жирность блюд, при сохранении симптомов — к терапевту","is_correct":true},{"id":3,"text":"Перейти только на молоко и хлеб","is_correct":false},{"id":4,"text":"Терпеть — само пройдёт","is_correct":false}]',
   'Изжога 2 недели подряд — сигнал. Сначала корректируем питание: меньше порция, никаких ночных перекусов, исключить острое и жирное. Если за неделю не пройдёт — омепразол на 14 дней + к терапевту. Постоянная изжога без лечения превращается в эзофагит и язву.'),
  (10, 'choice', 'Запор у вахтовиков — частая жалоба. Главная причина:',
   '[{"id":1,"text":"Стресс","is_correct":false},{"id":2,"text":"Мало клетчатки + мало воды + сидячая поза","is_correct":true},{"id":3,"text":"Холодная погода","is_correct":false},{"id":4,"text":"Несовместимость продуктов","is_correct":false}]',
   'Запор у вахтовиков — это комбинация: мало овощей и клетчатки, мало воды (2 литра нужно), сидячая работа в технике. Хронический запор после 5-7 лет ведёт к геморрою, дивертикулёзу, повышает риск рака толстой кишки.'),
  (11, 'scenario', 'Ты собираешься на вахту 30/60. Что положить в сумку с едой/таблетками?',
   '[{"id":1,"text":"Только бутылку коньяка от усталости","is_correct":false},{"id":2,"text":"Овсянка, орехи, сухофрукты, зелёный чай, витамины, аптечка ЖКТ (омепразол, смекта, уголь)","is_correct":true},{"id":3,"text":"Только сигареты и кофе","is_correct":false},{"id":4,"text":"Ничего — всё дадут на промысле","is_correct":false}]',
   'Базовая сумка вахтовика: овсянка (на завтрак если не успел), орехи (перекус), сухофрукты (от запора и для энергии), зелёный чай (вместо кофе), витамины (овощей мало), аптечка ЖКТ. Алкоголь запрещён, и реально опасен для здоровья. Сигареты и кофе натощак — путь к язве.'),
  (12, 'truefalse', 'После 5 лет вахты гастрит — это нормально и неизбежно.',
   '[{"id":1,"text":"Верно","is_correct":false},{"id":2,"text":"Неверно","is_correct":true}]',
   'Гастрит появляется у 80% вахтовиков по статистике, но у тех 20%, кто соблюдает правила — нет. Завтрак, перекусы, овощи, режим, нет кофе натощак — и желудок выдержит и 30 лет вахты. Игорь Скляров (33 года вахты, никакой язвы) — реальный пример.')
) AS q(so, qt, qtext, opts, expl);

COMMIT;
